return $build(array(
 'key'=>'pancasila-sd6-fase-c','grade'=>'sd_6','category'=>'ppkn','slug'=>'pendidikan-pancasila-kelas-6-keputusan-adil-dan-kewargaan',
 'title'=>'Pendidikan Pancasila Kelas 6 — Keputusan Adil dan Kewargaan',
 'summary'=>'Delapan bab pendalaman Fase C: menilai sumber sejarah, kesatuan nilai, hak dan kewajiban, tujuan negara, musyawarah, keberagaman, kerja sama wilayah dan proyek kewargaan. Kasus serta refleksi original tanpa materi agama/muatan lokal.',
 'objectives'=>"Memisahkan fakta sejarah dan penafsiran.\nMenilai keputusan menggunakan nilai Pancasila serta penghormatan hak.\nMenyusun musyawarah dan aksi bersama yang inklusif.\nMengevaluasi dampak tindakan dengan bukti dan batas yang jelas.",
 'prerequisites'=>'Pancasila kelas 5. Gunakan situasi rekaan; tidak meminta agama, politik, alamat atau masalah pribadi keluarga. Kuis tidak membuktikan perilaku sehari-hari tanpa observasi.',
 'source'=>'Materi/kasus/soal original Project Pintar 2026. BSKAP Pancasila Fase C https://repositori.kemendikdasmen.go.id/33626/ . Sumber sejarah https://harlahpancasila.bpip.go.id/kirab-pancasila/ ; konstitusi https://jdih.dpr.go.id/index/uu1945 . Pembagian bab sendiri, bukan salinan buku atau nasihat hukum kasus pribadi.',
),array(
 ['Bab 1. Menilai sumber perumusan','Peristiwa, dokumen, dan penafsiran','Memeriksa klaim sejarah tanpa menyamakan semua tahap perumusan.',
 'Sumber sejarah perlu diperiksa asal, waktu dan konteksnya. Dokumen, pidato serta keputusan forum dapat menjadi bukti untuk pertanyaan yang berbeda. Ringkasan buatan pembaca tidak boleh diubah menjadi kutipan tokoh. Ketika dua penjelasan tampak berbeda, periksa apakah membahas peristiwa atau tahap yang sama sebelum menyatakan salah satu salah.',
 'Contoh dua kartu: A membahas pidato 1 Juni 1945; B membahas keputusan PPKI 18 Agustus 1945. Kedua kartu tidak otomatis bertentangan karena merujuk tahap berbeda. Tambahkan kartu Piagam Jakarta 22 Juni untuk melihat rangkaian. Nilai kerja sama dapat direfleksikan, tetapi kalimat refleksi bukan bunyi dokumen sejarah.',
 ['Mengapa kartu A dan B tidak otomatis bertentangan?','Apa yang perlu dicatat selain tanggal?','Bagaimana menandai refleksi sendiri?'],
 ['Karena membahas tahap serta forum berbeda.','Asal sumber, pelaku/forum, konteks dan hasil peristiwa.','Tulis sebagai penafsiran/refleksi dengan alasan, bukan kutipan tokoh.'],
 'Gunakan rujukan BPIP dan tidak membuat ucapan tokoh. Hindari lomba hafalan yang menghapus hubungan peristiwa. Anak boleh menyusun tiga kartu tanpa mencetak gambar berhak cipta.',
 [['Sebelum membandingkan dua klaim sejarah, periksa ...',['jumlah huruf','peristiwa dan sumber yang dibahas','warna layar','kepopuleran pengirim'],1,'Perbedaan dapat muncul karena sumber membahas tahap yang berbeda.'],['Refleksi pembaca sebaiknya ...',['diklaim ucapan tokoh','disembunyikan','dibedakan dari kutipan/fakta','mengganti dokumen resmi'],2,'Penafsiran perlu jelas statusnya agar tidak disalahpahami sebagai sumber asli.']]],
 ['Bab 2. Nilai dalam keputusan','Menimbang lebih dari satu kepentingan','Menggunakan kesatuan sila untuk menilai tindakan dan akibatnya.',
 'Nilai Pancasila saling mendukung ketika digunakan untuk menilai keputusan. Menghormati manusia, menjaga persatuan, bermusyawarah dan mengupayakan keadilan perlu dipikirkan bersama. Kesepakatan mayoritas tidak membenarkan penghinaan atau pengabaian keselamatan. Keputusan baik mempertimbangkan tujuan, hak, kebutuhan serta akibat bagi orang yang lebih sedikit suaranya.',
 'Kasus rekaan: sebagian besar kelompok memilih lomba cepat, tetapi dua anggota membutuhkan cara partisipasi berbeda. Mereka dapat menambah pilihan tantangan kerja sama dan waktu fleksibel. Tujuan belajar tetap tercapai tanpa menyingkirkan anggota. Perubahan bukan hadiah khusus, melainkan upaya agar kesempatan bermakna tersedia.',
 ['Mengapa suara terbanyak belum cukup menilai keputusan?','Apa alternatif pada contoh?','Nilai apa yang saling berhubungan dalam keputusan itu?'],
 ['Hak, keselamatan dan kebutuhan semua anggota tetap perlu dihormati.','Pilihan tantangan kerja sama dan waktu yang sesuai.','Kemanusiaan, persatuan, musyawarah dan keadilan dalam kesempatan.'],
 'Tidak meminta anak mengungkap diagnosis atau keyakinan. Hindari label anak normal/tidak normal. Fokus pada rancangan kegiatan serta alasan yang dapat dipahami.',
 [['Keputusan mayoritas tetap harus ...',['menghormati hak dan keselamatan','menghapus semua usul lain','memaksa bentuk tubuh sama','melarang kebutuhan berbeda'],0,'Jumlah suara tidak menghapus kewajiban menghormati martabat dan keselamatan.'],['Pilihan partisipasi berbeda dapat bertujuan ...',['memberi ejekan','membuka kesempatan adil','menghapus semua tujuan','memisahkan selamanya'],1,'Penyesuaian dapat membantu peserta mencapai tujuan belajar secara adil.']]],
 ['Bab 3. Tanggung jawab warga','Hak, kewajiban, dan penyelesaian masalah','Membedakan tanggung jawab dari penghukuman yang merendahkan.',
 'Hak dan kewajiban berjalan dalam kehidupan bersama. Menjaga fasilitas, menghormati orang lain dan menaati aturan yang sah merupakan bentuk tanggung jawab. Jika ada masalah, cari fakta, dengarkan pihak terkait dan gunakan penyelesaian yang wajar. Kesalahan seseorang tidak memberi izin menyebarkan data pribadi atau menjadikannya sasaran perundungan.',
 'Kasus rekaan: sebuah buku kembali dengan halaman lepas. Petugas mencatat kondisi dan berbicara dengan peminjam serta pendamping, bukan menempel foto peminjam di papan malu. Mereka memeriksa penyebab dan cara perbaikan sesuai aturan. Belum mengetahui penyebab berarti tidak boleh langsung menuduh seseorang sengaja merusak.',
 ['Apa fakta yang diketahui pada contoh?','Apa yang belum boleh disimpulkan?','Mengapa papan malu tidak tepat?'],
 ['Halaman buku lepas saat kembali.','Bahwa peminjam sengaja merusak tanpa pemeriksaan.','Karena merendahkan serta dapat menyebarkan data pribadi, bukan menyelesaikan masalah secara adil.'],
 'Jangan membahas kasus anak nyata di depan kelompok. Jika terjadi perundungan atau bahaya, bantu anak menghubungi orang dewasa tepercaya. Pelajaran bukan pengganti penanganan perlindungan anak.',
 [['Sebelum menyalahkan peminjam, petugas perlu ...',['menyebarkan fotonya','memeriksa fakta dan mendengar penjelasan','mengarang saksi','menghapus aturan'],1,'Pemeriksaan fakta dan penjelasan membantu penyelesaian yang wajar.'],['Halaman lepas membuktikan ...',['niat merusak pasti','semua pengguna ceroboh','kondisi buku, belum niat seseorang','peminjam tidak punya hak'],2,'Kondisi benda tidak otomatis membuktikan niat atau seluruh penyebab.']]],
 ['Bab 4. Tujuan negara dan keseharian','Menghubungkan konstitusi dengan kepedulian','Menjelaskan contoh nilai tujuan negara tanpa mengarang pasal.',
 'Pembukaan UUD 1945 memuat tujuan negara yang antara lain berkaitan dengan perlindungan, kesejahteraan, pendidikan dan ketertiban dunia. Hubungan dengan keseharian dapat dibahas melalui layanan yang aman dan kesempatan belajar. Contoh kelas adalah penafsiran pendidikan; tidak semua tindakan atau aturan sekolah merupakan teks konstitusi.',
 'Kegiatan rekaan menyiapkan bahan baca yang lebih mudah dijangkau semua peserta. Tujuannya membantu kesempatan belajar, sehingga dapat dihubungkan dengan perhatian pada pendidikan. Namun kalimat tentang ukuran rak atau jadwal pinjam bukan bagian Pembukaan. Untuk memastikan bunyi resmi, periksa dokumen, bukan hanya ringkasan poster.',
 ['Apa hubungan contoh dengan tujuan pendidikan?','Apakah ukuran rak tertulis dalam Pembukaan?','Mengapa dokumen resmi perlu dibaca?'],
 ['Bahan yang dapat dijangkau membantu kesempatan belajar.','Tidak; itu rincian rancangan kegiatan pada contoh.','Untuk membedakan bunyi konstitusi dari penjelasan atau penafsiran pembaca.'],
 'Tidak memaksa hafalan panjang atau membahas sengketa hukum keluarga. Ajarkan cara menyebut sumber dan batas penafsiran. Gunakan dokumen resmi JDIH DPR sebagai acuan.',
 [['Rincian ukuran rak pada contoh merupakan ...',['pasal baru UUD','rancangan kegiatan','kutipan Pembukaan','keputusan pengadilan'],1,'Ukuran rak adalah pilihan kegiatan, bukan bunyi konstitusi.'],['Ringkasan konstitusi sebaiknya ...',['menggantikan semua teks resmi','tanpa sumber','dibedakan dari bunyi resmi','ditulis sebagai kutipan palsu'],2,'Ringkasan menggunakan kata sendiri dan tidak menggantikan teks resmi.']]],
 ['Bab 5. Musyawarah dengan bukti','Pilihan, dampak, dan evaluasi kesepakatan','Mengembangkan keputusan bersama yang dapat ditinjau secara adil.',
 'Musyawarah tidak selesai hanya setelah memilih usul. Catat alasan, manfaat, risiko, pembagian tanggung jawab dan waktu peninjauan. Pendapat yang belum disepakati tetap dirangkum dengan hormat. Informasi baru dapat menjadi alasan memperbaiki keputusan. Perubahan yang terbuka berbeda dari mengganti kesepakatan diam-diam.',
 'Kasus rekaan: kelompok memilih dua jadwal berbagi alat. Setelah seminggu simulasi, catatan menunjukkan satu kelompok selalu mendapat waktu paling pendek. Mereka meninjau aturan dan menggilir jadwal. Keputusan awal tidak disembunyikan; perubahan serta alasannya dicatat supaya peserta memahami prosesnya.',
 ['Apa bukti perlunya peninjauan?','Apa perbaikan yang dipilih?','Mengapa alasan perubahan dicatat?'],
 ['Satu kelompok terus mendapat waktu lebih pendek.','Menggilir jadwal agar kesempatan lebih seimbang.','Agar keputusan transparan dan dapat dipahami/dievaluasi bersama.'],
 'Gunakan catatan rekaan tanpa nama anak. Beri kesempatan menyampaikan pendapat lewat tulisan/gambar. Jangan menafsirkan diam sebagai persetujuan otomatis.',
 [['Kesepakatan yang menimbulkan masalah sebaiknya ...',['ditinjau dengan bukti','dipertahankan tanpa pertanyaan','diubah diam-diam','disalahkan ke satu anak'],0,'Bukti dampak membantu memperbaiki kesepakatan secara terbuka.'],['Diam dalam diskusi berarti ...',['pasti setuju','belum tentu setuju; perlu ruang respons','selalu menolak','tidak punya hak'],1,'Peserta mungkin belum siap atau memakai cara komunikasi berbeda.']]],
 ['Bab 6. Keberagaman dan informasi','Menolak stereotip, memeriksa pesan','Menilai informasi tentang kelompok tanpa menggeneralisasi.',
 'Pesan yang menyebut semua orang dari kelompok tertentu memiliki sifat sama perlu diperiksa kritis. Satu pengalaman tidak mewakili seluruh kelompok. Menghargai keberagaman berarti melihat manusia sebagai individu serta memahami konteks budaya. Sebelum meneruskan informasi, periksa sumber, bukti, tujuan dan kemungkinan dampaknya pada orang lain.',
 'Pesan rekaan menyatakan semua warga wilayah Z tidak suka bekerja sama karena satu kegiatan batal. Pesan itu melompat dari satu kejadian ke penilaian semua orang; penyebab batal belum diketahui. Respons yang lebih tepat ialah tidak menyebarkannya, meminta informasi yang sah dan membahas peristiwa tanpa menyerang identitas.',
 ['Apa masalah penalaran dalam pesan?','Apa yang belum diketahui?','Apa respons yang menghargai keberagaman?'],
 ['Menggeneralisasi satu kejadian menjadi sifat semua warga.','Penyebab kegiatan batal serta konteksnya.','Tidak meneruskan stereotip dan memeriksa fakta peristiwa secara santun.'],
 'Wilayah Z sepenuhnya rekaan. Tidak perlu mencari atau menampilkan ujaran kebencian nyata. Jika anak mendapat ancaman, simpan bukti secara aman dengan pendamping dan cari bantuan yang sesuai.',
 [['Satu kegiatan batal cukup untuk menilai semua warga ...',['selalu cukup','tidak cukup','jika pesannya panjang','jika banyak dibagikan'],1,'Satu kejadian tidak mewakili sifat seluruh warga dan penyebabnya belum diketahui.'],['Sebelum membagikan pesan tentang kelompok, periksa ...',['kecepatan kirim','jumlah emoji saja','sumber, bukti dan dampak','warna latar saja'],2,'Pemeriksaan sumber dan dampak membantu mencegah stereotip serta informasi keliru.']]],
 ['Bab 7. Kerja sama lintas wilayah','Batas administratif dan kebutuhan bersama','Menghubungkan kabupaten/kota serta provinsi dengan persatuan.',
 'Wilayah administratif membantu pembagian urusan pemerintahan, tetapi kehidupan warga saling terkait. Kabupaten/kota berada dalam provinsi sebagai bagian NKRI. Masalah sungai, transportasi atau pertukaran barang dapat melintasi batas sehingga membutuhkan kerja sama. Menjaga persatuan tidak menghapus kekhasan daerah atau melarang kritik yang santun.',
 'Dua wilayah rekaan berbagi aliran sungai. Warga hulu dan hilir mengusulkan pengelolaan sampah bersama melalui pihak yang berwenang. Mereka perlu data sumber masalah, bukan langsung menyalahkan semua warga satu wilayah. Anak berperan mengusulkan dan belajar, tidak turun ke sungai atau menangani sampah berbahaya.',
 ['Mengapa masalah sungai perlu kerja sama?','Mengapa tidak langsung menyalahkan wilayah lain?','Apa peran aman bagi anak pada contoh?'],
 ['Aliran dan dampaknya dapat melintasi batas administratif.','Penyebab perlu diperiksa dengan bukti dan warga tidak semuanya berperan sama.','Mempelajari data rekaan serta menyusun usul kepada pendamping.'],
 'Tidak meminta alamat rumah atau lokasi sungai yang dikunjungi anak. Kegiatan tidak mencakup pembersihan sungai nyata. Batas/pemerintahan aktual diperiksa dari sumber resmi bila diperlukan.',
 [['Batas administratif berarti masalah lingkungan ...',['selalu berhenti di batas','dapat tetap melintasi batas','tidak perlu dikelola','hanya milik anak'],1,'Aliran air dan dampak lingkungan tidak selalu mengikuti batas pemerintahan.'],['Kerja sama yang tepat diawali dengan ...',['tuduhan massal','kompetisi menyalahkan','data dan tujuan bersama','aksi berbahaya sendiri'],2,'Data serta tujuan bersama membantu menyusun tindakan yang relevan dan adil.']]],
 ['Bab 8. Proyek kewargaan','Dari rencana hingga pertanggungjawaban','Menyusun aksi kecil dengan indikator, akses dan evaluasi.',
 'Proyek kewargaan menghubungkan kepedulian dengan tindakan yang dapat dipertanggungjawabkan. Tentukan masalah, pihak terdampak, tujuan, peran, sumber daya dan indikator hasil. Beri pilihan partisipasi sesuai kemampuan. Laporan akhir perlu menyebut capaian sekaligus hal yang belum selesai, bukan hanya foto kegiatan atau pujian.',
 'Proyek rekaan: membuat petunjuk peminjaman alat yang mudah dibaca. Sebelum perbaikan, 3 dari 5 langkah jelas pada uji contoh; sesudahnya 5 dari 5. Kelompok mencatat cara uji dan jumlah penguji terbatas. Mereka belum menyimpulkan semua pengguna pasti memahami; langkah lanjut ialah uji lebih beragam dengan pendamping.',
 ['Apa indikator pada proyek?','Apa hasil yang dapat dilaporkan?','Apa batas kesimpulannya?'],
 ['Jumlah langkah yang jelas pada uji yang ditetapkan.','Dari 3 menjadi 5 langkah jelas dari total 5 pada contoh.','Penguji dan kondisi terbatas, sehingga tidak mewakili semua pengguna.'],
 'Gunakan data rekaan atau pengamatan anonim dengan izin pendamping. Tidak mengumpulkan uang, identitas atau tanda tangan warga. Aksi sipil aman dapat menunjukkan kepedulian tanpa risiko fisik.',
 [['Laporan proyek yang bertanggung jawab memuat ...',['hasil dan keterbatasan','pujian saja','nama lengkap semua anak','klaim pasti sempurna'],0,'Capaian serta batas pengamatan perlu disampaikan jujur.'],['Hasil uji kecil dapat digeneralisasi ke semua pengguna ...',['selalu','tanpa sumber','tidak otomatis','jika judulnya menarik'],2,'Generalisasi membutuhkan cakupan bukti yang sesuai, bukan satu uji kecil.']]],
));
